<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2048 Dark</title>
    <style>
        :root {
            --bg-color: #1a1a1a;
            --board-bg: #333;
            --empty-tile: #444;
            --text-light: #eee;
            --text-dark: #333;
            --accent: #f67c5f;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-light);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        .game-container {
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .header {
            width: 100%;
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        #score {
            font-size: 24px;
            font-weight: bold;
            background: var(--board-bg);
            padding: 5px 15px;
            border-radius: 5px;
        }

        #reset {
            padding: 8px 16px;
            font-size: 16px;
            cursor: pointer;
            background-color: var(--accent);
            color: white;
            border: none;
            border-radius: 5px;
            font-weight: bold;
            transition: background 0.2s;
        }

        #reset:hover {
            background-color: #e66a4e;
        }

        #board {
            display: grid;
            grid-template-columns: repeat(4, 80px);
            grid-template-rows: repeat(4, 80px);
            gap: 10px;
            background-color: var(--board-bg);
            padding: 10px;
            border-radius: 6px;
            box-shadow: 0 4px 10px rgba(0,0,0,0.5);
        }

        .tile {
            width: 80px;
            height: 80px;
            background-color: var(--empty-tile);
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
            font-weight: bold;
            transition: transform 0.1s ease-out, background-color 0.15s;
        }

        /* Tile Colors */
        .tile-2 { background-color: #eee4da; color: var(--text-dark); }
        .tile-4 { background-color: #ede0c8; color: var(--text-dark); }
        .tile-8 { background-color: #f2b179; color: var(--text-light); }
        .tile-16 { background-color: #f59564; color: var(--text-light); }
        .tile-32 { background-color: #f67c5f; color: var(--text-light); }
        .tile-64 { background-color: #f65d50; color: var(--text-light); }
        .tile-128 { background-color: #ed6f5a; color: var(--text-light); font-size: 24px; }
        .tile-256 { background-color: #ed6f5a; color: var(--text-light); font-size: 24px; }
        .tile-512 { background-color: #ed6f5a; color: var(--text-light); font-size: 22px; }
        .tile-1024 { background-color: #ed6f5a; color: var(--text-light); font-size: 20px; }
        .tile-2048 { background-color: #ed6f5a; color: var(--text-light); font-size: 18px; }
    </style>
</head>
<body>

<div class="game-container">
    <div class="header">
        <div id="score">Score: 0</div>
        <button id="reset">Reset</button>
    </div>
    <div id="board"></div>
</div>

<script>
(function() {
    const size = 4;
    let grid = [];
    let scoreVal = 0;

    const boardEl = document.getElementById('board');
    const scoreEl = document.getElementById('score');
    const resetBtn = document.getElementById('reset');

    function transpose(m) {
        return m[0].map((_, i) => m.map(row => row[i]));
    }

    function flipVertical(m) {
        return [...m].reverse();
    }

    function flipHorizontal(m) {
        return m.map(row => [...row].reverse());
    }

    // Core logic: processes a single row
    function processRow(row) {
        let newRow = row.filter(x => x !== 0);
        let addedScore = 0;
        let changed = false;
        let mergedRow = [];

        for (let i = 0; i < newRow.length; i++) {
            if (i + 1 < newRow.length && newRow[i] === newRow[i + 1]) {
                let val = newRow[i] * 2;
                mergedRow.push(val);
                addedScore += val;
                i++; // Skip next element as it's merged
            } else {
                mergedRow.push(newRow[i]);
            }
        }

        while (mergedRow.length < size) {
            mergedRow.push(0);
        }

        // Check if row actually changed in value or length
        if (JSON.stringify(row) !== JSON.stringify(mergedRow)) {
            changed = true;
        }

        return { mergedRow, addedScore, changed };
    }

    function moveLeft(m) {
        let newGrid = m.map(row => [...row]);
        let totalAdded = 0;
        let changed = false;

        for (let i = 0; i < size; i++) {
            const { mergedRow, addedScore, changed: rowChanged } = processRow(m[i]);
            if (rowChanged) changed = true;
            totalAdded += addedScore;
            newGrid[i] = mergedRow;
        }
        return { newGrid, addedScore: totalAdded, changed };
    }

    function moveUp(m) {
        const trans = transpose(m);
        const res = moveLeft(trans);
        return { newGrid: transpose(res.newGrid), addedScore: res.addedScore, changed: res.changed };
    }

    function moveRight(m) {
        const flipped = flipHorizontal(m);
        const res = moveLeft(flipped);
        const unflipped = flipHorizontal(res.newGrid);
        return { newGrid: unflipped, addedScore: res.addedScore, changed: res.changed };
    }

    function moveDown(m) {
        const flipped = flipVertical(m);
        const res = moveUp(flipped);
        const unflipped = flipVertical(res.newGrid);
        return { newGrid: unflipped, addedScore: res.addedScore, changed: res.changed };
    }

    function spawnTile() {
        const emptyCells = [];
        for (let r = 0; r < size; r++) {
            for (let c = 0; c < size; c++) {
                if (grid[r][c] === 0) emptyCells.push({ r, c });
            }
        }
        if (emptyCells.length === 0) return;
        const { r, c } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
        grid[r][c] = Math.random() < 0.9 ? 2 : 4;
    }

    function updateUI() {
        boardEl.innerHTML = '';
        scoreEl.innerText = `Score: ${scoreVal}`;
        for (let r = 0; r < size; r++) {
            for (let c = 0; c < size; c++) {
                const tile = document.createElement('div');
                tile.classList.add('tile');
                const val = grid[r][c];
                if (val > 0) {
                    tile.innerText = val;
                    tile.classList.add('tile-' + val);
                }
                boardEl.appendChild(tile);
            }
        }
    }

    function reset() {
        grid = Array.from({ length: size }, () => Array(size).fill(0));
        scoreVal = 0;
        spawnTile();
        spawnTile();
        updateUI();
    }

    // Expose API to window
    window.game = {
        size,
        reset,
        move: function(dir) {
            let res;
            if (dir === 'left') res = moveLeft(grid);
            else if (dir === 'right') res = moveRight(grid);
            else if (dir === 'up') res = moveUp(grid);
            else if (dir === 'down') res = moveDown(grid);
            else return false;

            if (res.changed) {
                grid = res.newGrid;
                scoreVal += res.addedScore;
                spawnTile();
                updateUI();
                return true;
            }
            return false;
        },
        board: () => grid.map(row => [...row]),
        setBoard: (arr) => {
            grid = arr.map(row => [...row]);
            scoreVal = 0;
            updateUI();
        },
        score: () => scoreVal
    };

    // Listeners
    resetBtn.addEventListener('click', reset);

    window.addEventListener('keydown', (e) => {
        if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
            e.preventDefault();
        }
        if (e.key === 'ArrowUp') window.game.move('up');
        if (e.key === 'ArrowDown') window.game.move('down');
        if (e.key === 'ArrowLeft') window.game.move('left');
        if (e.key === 'ArrowRight') window.game.move('right');
    });

    // Start
    reset();

})();
</script>
</body>
</html>

